mapper.select:
SELECT b.id, b.user_id, u.username, u.real_name, u.phone, u.credit_score, u.credit_level, b.list_type, b.reason, b.trigger_rule, b.effective_time, b.expire_time, b.status, b.create_time FROM credit_blacklist b LEFT JOIN sys_user u ON u.id = b.user_id WHERE b.deleted = 0
AND b.status = #{status}
AND b.list_type = #{listType}
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY b.status ASC, b.id DESC
